import {zipSync,unzipSync,strToU8,strFromU8} from './vendor/fflate.js';
import {uid,step,questionTypes,questionType} from './model.js';
const ns='https://github.com/VladimirKhil/SI/blob/master/assets/siq_5.xsd';
export const escapeXML=v=>String(v??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c])).replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g,'');
const tag=(n,v)=>`<${n}>${escapeXML(v)}</${n}>`;
const folder={image:'Images',audio:'Audio',video:'Video'};
const filename=s=>`${s.mediaId}.${(s.filename?.split('.').pop()||'bin').replace(/[^a-zA-Z0-9]/g,'')||'bin'}`;
const duration=n=>[Math.floor(n/3600),Math.floor(n/60)%60,n%60].map(v=>String(v).padStart(2,'0')).join(':');
function item(s){return `<item type="${s.type}"${s.mediaId?' isRef="True"':''}${s.placement?` placement="${escapeXML(s.placement)}"`:''}${s.duration?` duration="${duration(s.duration)}"`:''} waitForFinish="${s.wait===false?'False':'True'}">${escapeXML(s.mediaId?filename(s):s.value)}</item>`;}
export function contentXML(p){return `<?xml version="1.0" encoding="utf-8"?><package xmlns="${ns}" name="${escapeXML(p.name)}" version="5" id="${escapeXML(p.id)}" date="${new Date().toLocaleDateString('ru-RU',{timeZone:'Asia/Yerevan'})}" difficulty="${p.difficulty}" language="${escapeXML(p.language)}" generator="SIGameMaker"><info><authors>${p.author?tag('author',p.author):''}</authors>${tag('comments',p.description)}</info><rounds>${p.rounds.map(r=>`<round name="${escapeXML(r.name)}" type="${r.type}"><themes>${r.themes.map(t=>`<theme name="${escapeXML(t.name)}"><questions>${t.questions.map(q=>{const type=questionType(q);if(!Object.hasOwn(questionTypes,type))throw Error('Неподдерживаемый тип вопроса: '+type);if(q.steps.filter(s=>s.type==='answer').length>1)throw Error('Повторные попытки с подсказками пока не поддерживаются: SIGame раскрывает ответ после первого таймера');const marker=q.steps.findIndex(s=>s.type==='answer');const before=q.steps.slice(0,marker<0?undefined:marker).filter(s=>s.type!=='answer');const after=marker<0?[]:q.steps.slice(marker+1).filter(s=>s.type!=='answer');return `<question price="${q.price}" type="${type}"><info><sources>${q.source?tag('source',q.source):''}</sources>${tag('showmanComments',q.comment)}</info><params><param name="question" type="content">${before.map(item).join('')}</param>${q.steps.find(s=>s.type==='answer')?.duration?`<param name="answerDuration">${q.steps.find(s=>s.type==='answer').duration}</param>`:''}${after.length?`<param name="answer" type="content">${after.map(item).join('')}</param>`:''}</params><right>${[q.answer,...q.alternatives.split('\n')].filter(a=>a.trim()).map(a=>tag('answer',a.trim())).join('')}</right>${q.wrong?`<wrong>${q.wrong.split('\n').filter(a=>a.trim()).map(a=>tag('answer',a.trim())).join('')}</wrong>`:''}</question>`;}).join('')}</questions></theme>`).join('')}</themes></round>`).join('')}</rounds></package>`;}
export async function exportSIQ(p,media){const files={'content.xml':strToU8(contentXML(p))};for(const r of p.rounds)for(const t of r.themes)for(const q of t.questions)for(const s of q.steps)if(folder[s.type]&&s.mediaId){const blob=media.get(s.mediaId);if(!blob)throw Error('Не найден файл '+s.filename);files[`${folder[s.type]}/${filename(s)}`]=new Uint8Array(await blob.arrayBuffer());}return zipSync(files,{level:0});}
const children=(el,name)=>Array.from(el?.children||[]).filter(x=>x.localName===name);
const child=(el,name)=>children(el,name)[0];const txt=el=>el?.textContent||'';
export function importSIQ(bytes){
 if(bytes.length>250*1024*1024)throw Error('Пак больше 250 МБ. Разделите его на несколько паков.');let expanded=0;const files=unzipSync(bytes,{filter:f=>{expanded+=f.originalSize;if(expanded>500*1024*1024)throw Error('Распакованный пак превышает 500 МБ');return true;}});if(!files['content.xml'])throw Error('В архиве не найден content.xml');
 const doc=new DOMParser().parseFromString(strFromU8(files['content.xml']),'application/xml');if(doc.querySelector('parsererror'))throw Error('Повреждённый XML в паке');const root=doc.documentElement;if(root.localName!=='package')throw Error('Это не пакет SIGame');const version=Number(root.getAttribute('version'));if(version!==4&&version!==5)throw Error('Поддерживаются пакеты SIQ 4 и 5');const media=new Map(),refs=new Map();
 function readItem(el,legacy=false){const rawType=el.getAttribute('type')||'text';if(rawType==='marker')return step('answer');const type=rawType==='voice'?'audio':rawType==='say'?'text':rawType;if(!['text','image','audio','video'].includes(type))throw Error(`Тип содержимого «${type}» пока не поддерживается. Импорт отменён, чтобы не потерять данные.`);const value=txt(el),s=step(type,value);s.wait=(el.getAttribute('waitForFinish')||'true').toLowerCase()!=='false';s.placement=el.getAttribute('placement')||(rawType==='say'?'replic':undefined);const d=el.getAttribute('duration');s.duration=d?d.split(':').reduce((a,n)=>a*60+Number(n),0):Number(el.getAttribute('time'))||0;const isRef=(el.getAttribute('isRef')||'').toLowerCase()==='true'||legacy&&value.startsWith('@');if(folder[type]){if(!isRef)throw Error('В паке есть внешние медиа. Сначала встройте их в исходном редакторе.');const name=value.replace(/^@/,'');let decoded=name;try{decoded=decodeURIComponent(name);}catch{}const path=[`${folder[type]}/${name}`,`${folder[type]}/${decoded}`,`${folder[type]}/${encodeURIComponent(decoded)}`].find(k=>files[k]);if(!path)throw Error(`Не найден медиафайл: ${name}`);let id=refs.get(path);if(!id){id=uid();refs.set(path,id);const ext=decoded.split('.').pop().toLowerCase();const mime=({png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',gif:'image/gif',mp3:'audio/mpeg',wav:'audio/wav',ogg:'audio/ogg',mp4:'video/mp4',webm:'video/webm'})[ext]||`${type}/${ext}`;media.set(id,new Blob([files[path]],{type:mime}));}s.mediaId=id;s.filename=decoded;s.value='';}return s;}
 const info=child(root,'info'),p={id:root.getAttribute('id')||uid(),name:root.getAttribute('name')||'Импортированный пак',author:children(child(info,'authors'),'author').map(txt).join(', '),description:txt(child(info,'comments')),difficulty:Number(root.getAttribute('difficulty'))||5,language:root.getAttribute('language')||'ru-RU',rounds:[]};
 for(const re of children(child(root,'rounds'),'round')){const r={id:uid(),name:re.getAttribute('name')||'Раунд',type:re.getAttribute('type')||'standard',themes:[]};if(!['standard','final'].includes(r.type))throw Error('Неизвестный тип раунда');for(const te of children(child(re,'themes'),'theme')){const t={id:uid(),name:te.getAttribute('name')||'Тема',questions:[]};for(const qe of children(child(te,'questions'),'question')){const legacyType=child(qe,'type'),qt=qe.getAttribute('type')||legacyType?.getAttribute('name')||'simple';const type=qt==='stake'||version===4&&qt==='auction'?'stake':['simple','default','withButton',''].includes(qt)?'simple':null;if(child(qe,'script')||!type)throw Error('Поддерживаются обычные вопросы и аукционы. Другие типы и скрипты пока нельзя импортировать без потери логики.');if(children(legacyType,'param').length)throw Error('Пак содержит дополнительные параметры типа вопроса. Импорт отменён, чтобы не потерять их.');const qi=child(qe,'info'),answers=children(child(qe,'right'),'answer').map(txt);const q={id:uid(),type,price:Number(qe.getAttribute('price'))||0,answer:answers[0]||'',alternatives:answers.slice(1).join('\n'),wrong:children(child(qe,'wrong'),'answer').map(txt).join('\n'),comment:txt(child(qi,'showmanComments'))||txt(child(qi,'comments')),source:children(child(qi,'sources'),'source').map(txt).join('\n'),steps:[]};const params=children(child(qe,'params'),'param');if(params.some(p=>!['question','answer','answerDuration'].includes(p.getAttribute('name'))))throw Error('Пак содержит дополнительные параметры вопросов. Импорт отменён, чтобы не потерять их.');const qp=params.find(x=>x.getAttribute('name')==='question');if(qp){q.steps=children(qp,'item').map(e=>readItem(e));q.steps.push(step('answer'));q.steps.push(...children(params.find(x=>x.getAttribute('name')==='answer'),'item').map(e=>readItem(e)));}else{q.steps=children(child(qe,'scenario'),'atom').map(e=>readItem(e,true));if(!q.steps.some(s=>s.type==='answer'))q.steps.push(step('answer'));}const timer=params.find(x=>x.getAttribute('name')==='answerDuration');if(timer){const value=txt(timer);if(!/^\d+$/.test(value)||Number(value)>35999)throw Error('Некорректное время на ответ');const phase=q.steps.find(s=>s.type==='answer');if(phase)phase.duration=Number(value);}t.questions.push(q);}r.themes.push(t);}p.rounds.push(r);}if(!p.rounds.length)throw Error('В паке нет раундов');return {pack:p,media};}

